<ArdourMIDIBindings version="1.0.0" name="Reactive Performance MVP" manufacturer="Generic">

<!--
  Reactive Performance Mode MVP bridge map.

  This uses existing Cue actions so a controller can launch scene-style cue rows
  before the dedicated Reactive/trigger-action-* executor is available.
-->

