	<Binding channel="10" note="36" action="Cues/trigger-cue-0"/>
	<Binding channel="10" note="37" action="Cues/trigger-cue-1"/>
	<Binding channel="10" note="38" action="Cues/trigger-cue-2"/>
	<Binding channel="10" note="39" action="Cues/trigger-cue-3"/>
	<Binding channel="10" note="40" action="Cues/trigger-cue-4"/>
	<Binding channel="10" note="41" action="Cues/trigger-cue-5"/>
	<Binding channel="10" note="42" action="Cues/trigger-cue-6"/>
	<Binding channel="10" note="43" action="Cues/trigger-cue-7"/>

</ArdourMIDIBindings>
